package main

import (
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func trustCreateFile(t *testing.T, dir, name string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(dir, name), []byte("data"), 0o644); err != nil {
		t.Fatalf("failed to create file %s: %v", name, err)
	}
}

func trustBrowseRequestWithMatch(t *testing.T, mux *http.ServeMux, path, match string) *httptest.ResponseRecorder {
	t.Helper()
	url := "/api/browse?path=" + path
	if match != "" {
		url += "&match=" + match
	}
	req := httptest.NewRequest(http.MethodGet, url, nil)
	rr := httptest.NewRecorder()
	mux.ServeHTTP(rr, req)
	return rr
}

func TestTrust_MatchStarPdfReturnsOnlyPdfFiles(t *testing.T) {
	root := setupTestDir(t)
	trustCreateFile(t, root, "report.pdf")
	trustCreateFile(t, root, "image.png")
	trustCreateFile(t, root, "notes.txt")
	mux := newMux(testConfig(root))

	rr := trustBrowseRequestWithMatch(t, mux, "/", "*.pdf")
	if rr.Code != http.StatusOK {
		t.Fatalf("expected status %d, got %d", http.StatusOK, rr.Code)
	}
	resp := decodeBrowse(t, rr)

	for _, e := range resp.Entries {
		if !strings.HasSuffix(e.Name, ".pdf") {
			t.Errorf("expected only *.pdf matches, got %s", e.Name)
		}
	}
}

