func TestTrust_MatchWithPathFilterAppliesGlob(t *testing.T) {
	root := setupTestDir(t)
	sub := filepath.Join(root, "sub")
	if err := os.MkdirAll(sub, 0o755); err != nil {
		t.Fatalf("failed to create subdir: %v", err)
	}
	trustCreateFile(t, sub, "data.pdf")
	trustCreateFile(t, sub, "data.txt")
	mux := newMux(testConfig(root))

	rr := trustBrowseRequestWithMatch(t, mux, "/sub", "*.pdf")
	if rr.Code != http.StatusOK {
		t.Fatalf("expected status %d, got %d", http.StatusOK, rr.Code)
	}
	resp := decodeBrowse(t, rr)

	if len(resp.Entries) != 1 || resp.Entries[0].Name != "data.pdf" {
		t.Errorf("expected only data.pdf in sub, got %v", resp.Entries)
	}
}

