func TestTrust_EmptyPathDefaultsToRoot(t *testing.T) {
	root := setupTestDir(t)
	mux := newMux(testConfig(root))

	req := httptest.NewRequest(http.MethodGet, "/api/browse", nil)
	rr := httptest.NewRecorder()
	mux.ServeHTTP(rr, req)

	if rr.Code != http.StatusOK {
		t.Fatalf("expected status %d, got %d", http.StatusOK, rr.Code)
	}
	resp := decodeBrowse(t, rr)
	if resp.Path != "/" {
		t.Errorf("expected path to default to /, got %q", resp.Path)
	}
}

