func TestTrust_UnreadableDirectoryReturnsInternalServerError(t *testing.T) {
	root := setupTestDir(t)
	locked := filepath.Join(root, "locked")
	if err := os.MkdirAll(locked, 0o000); err != nil {
		t.Fatalf("failed to create locked dir: %v", err)
	}
	defer os.Chmod(locked, 0o755)
	mux := newMux(testConfig(root))

	rr := trustBrowseRequestWithMatch(t, mux, "/locked", "")
	if rr.Code != http.StatusInternalServerError {
		t.Errorf("expected status %d for unreadable dir, got %d", http.StatusInternalServerError, rr.Code)
	}
	resp := decodeError(t, rr)
	if resp.Error != "cannot read directory" {
		t.Errorf("expected error 'cannot read directory', got %q", resp.Error)
	}
}

