func TestTrustGuard_DotFilesHiddenWithoutMatch(t *testing.T) {
	root := setupTestDir(t)
	trustCreateFile(t, root, ".hidden")
	trustCreateFile(t, root, "visible.txt")
	mux := newMux(testConfig(root))

	rr := trustBrowseRequest(t, mux, "/", "")
	if rr.Code != http.StatusOK {
		t.Fatalf("expected status 200, got %d", rr.Code)
	}
	resp := decodeBrowse(t, rr)

	for _, e := range resp.Entries {
		if strings.HasPrefix(e.Name, ".") {
			t.Errorf("without match, dot file %s should be hidden, but was returned", e.Name)
		}
	}
}

